  desc "Local gateway between AI clients and MCP servers"
  homepage "https://github.com/dinstein/agent-hub"
  version "0.38.0"
  license "MIT"

  on_macos do
    on_arm do
      url "https://github.com/dinstein/agent-hub/releases/download/v0.38.0/agenthub-0.38.0-c9e0633-darwin-arm64.tar.gz"
      sha256 "560cbe2c46bd163d7c3114b854bf6ea14a38a1389251a5a99ceebbaf9489c4e7"
    end
    on_intel do
